/**
 * crypto-agent-prompt.js
 *
 * Uzima sirove podatke (Fear & Greed Index + CoinPaprika /tickers lista) i pravi
 * kompaktnu poruku koju AI agent može da pročita i na osnovu nje procijeni
 * gdje ima potencijala, a gdje je rizično.
 *
 * Radi na dva načina:
 *   1) n8n "Code" node (Run Once for All Items) – samo zalijepi cijeli fajl.
 *      Izlaz: [{ json: { message, summary } }]  -> u AI Agent node koristi polje $json.message
 *   2) Node.js iz terminala:
 *      node crypto-agent-prompt.js podaci.json            -> ispiše poruku
 *      node crypto-agent-prompt.js podaci.json --json     -> ispiše { message, summary }
 */

// ───────────────────────────── PODEŠAVANJA ─────────────────────────────
const CONFIG = {
  minMarketCap: 50_000_000,   // ispod ovoga coin se ignoriše (previše mali / manipulisan)
  minVolume24h: 1_000_000,    // ispod ovoga nema dovoljno likvidnosti
  liquidMarketCap: 100_000_000, // za liste "lideri/gubitnici" traži bar ovoliko...
  liquidVolume24h: 5_000_000,   // ...i bar ovoliki dnevni promet
  topByCap: 15,
  topMovers: 10,
  topVolumeSpikes: 8,
  topCandidates: 10,
  topRedFlags: 10,
  stableDepegPct: 1.0,        // stablecoin van ±1% od $1 = upozorenje
};

// Poznati stablecoini i "omotani"/staking derivati (duplikati BTC/ETH)
const STABLE_SYMBOLS = new Set([
  'USDT', 'USDC', 'DAI', 'USDS', 'SUSDS', 'USDE', 'SUSDE', 'USD1', 'FDUSD', 'TUSD', 'PYUSD',
  'USDD', 'FRAX', 'LUSD', 'GUSD', 'USDP', 'BUSD', 'RLUSD', 'USDX', 'USDG', 'USD0', 'EURC',
  'EURS', 'USTC', 'CRVUSD', 'GHO', 'USDB', 'USDY', 'BFUSD', 'USDF', 'USDTB', 'SYRUPUSDC',
]);
const WRAPPED_SYMBOLS = new Set([
  'WBTC', 'CBBTC', 'TBTC', 'LBTC', 'SOLVBTC', 'BTCB', 'WETH', 'STETH', 'WSTETH', 'WEETH',
  'RETH', 'CBETH', 'METH', 'EZETH', 'RSETH', 'OSETH', 'ETHX', 'SFRXETH', 'WBETH', 'JITOSOL',
  'MSOL', 'BNSOL', 'JUPSOL', 'STSOL', 'SAVAX', 'WTRX', 'WBNB', 'STHYPE', 'KHYPE',
]);

// ───────────────────────────── POMOĆNE ─────────────────────────────
const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v));
const round = (v, d = 2) => (v === null ? null : Math.round(v * 10 ** d) / 10 ** d);
const median = (arr) => {
  const a = arr.filter((x) => x !== null).sort((x, y) => x - y);
  if (!a.length) return null;
  const m = Math.floor(a.length / 2);
  return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
};
const pct = (v) => (v === null ? 'n/a' : `${v > 0 ? '+' : ''}${v.toFixed(1)}%`);
const usd = (v) => {
  if (v === null) return 'n/a';
  const a = Math.abs(v);
  if (a >= 1e12) return `$${(v / 1e12).toFixed(2)}T`;
  if (a >= 1e9) return `$${(v / 1e9).toFixed(2)}B`;
  if (a >= 1e6) return `$${(v / 1e6).toFixed(1)}M`;
  if (a >= 1e3) return `$${(v / 1e3).toFixed(1)}K`;
  return `$${v.toFixed(0)}`;
};
const price = (v) => {
  if (v === null) return 'n/a';
  if (v >= 1000) return `$${v.toFixed(0)}`;
  if (v >= 1) return `$${v.toFixed(2)}`;
  return `$${Number(v.toPrecision(3))}`; // npr. $0.0000123 umjesto $0.00
};

// ───────────────────────────── 1. IZVLAČENJE PODATAKA ─────────────────────────────
// Prima bilo šta (niz, n8n item-e, ugniježđene nizove) i razdvaja F&G od coina.
function extract(input) {
  const out = { fng: null, coins: [] };
  const walk = (node) => {
    if (Array.isArray(node)) return node.forEach(walk);
    if (!node || typeof node !== 'object') return;
    if (node.json && typeof node.json === 'object') return walk(node.json); // n8n item
    if (Array.isArray(node.data) && node.data[0] && 'value_classification' in node.data[0]) {
      out.fng = node.data;
      return;
    }
    if (node.quotes && node.quotes.USD) {
      out.coins.push(node);
      return;
    }
    if (Array.isArray(node.data)) walk(node.data); // npr. { data: [...] } omotač
  };
  walk(input);
  return out;
}

// ───────────────────────────── 2. NORMALIZACIJA + SKOROVI ─────────────────────────────
function normalizeCoin(c) {
  const q = c.quotes.USD;
  const mcap = num(q.market_cap) || 0;
  const vol = num(q.volume_24h) || 0;
  const ageYears = c.first_data_at ? (Date.now() - new Date(c.first_data_at).getTime()) / 3.15576e10 : null;
  return {
    rank: c.rank,
    symbol: String(c.symbol || '').trim().toUpperCase(),
    name: c.name,
    price: num(q.price),
    mcap,
    vol,
    volToCap: mcap > 0 ? vol / mcap : null,
    volChange24h: num(q.volume_24h_change_24h),
    ch1h: num(q.percent_change_1h),
    ch6h: num(q.percent_change_6h),
    ch24h: num(q.percent_change_24h),
    ch7d: num(q.percent_change_7d),
    fromAth: num(q.percent_from_price_ath),
    athDate: q.ath_date ? q.ath_date.slice(0, 10) : null,
    beta: num(c.beta_value),
    ageYears,
    totalSupply: num(c.total_supply),
    maxSupply: num(c.max_supply) || null,
  };
}

function isStable(c) {
  if (STABLE_SYMBOLS.has(c.symbol)) return true;
  // heuristika: cijena ~1$ + skoro nulta beta + mali pomaci
  return c.price !== null && Math.abs(c.price - 1) < 0.02 && c.beta !== null && Math.abs(c.beta) < 0.05
    && Math.abs(c.ch7d || 0) < 1;
}

function isWrapped(c, btc, eth) {
  if (WRAPPED_SYMBOLS.has(c.symbol)) return true;
  // heuristika: kreće se identično kao BTC ili ETH (ista beta i isti 7d pomak)
  return [btc, eth].some((p) => p && p.symbol !== c.symbol && c.beta !== null && p.beta !== null
    && Math.abs(c.beta - p.beta) < 0.01 && Math.abs((c.ch7d || 0) - (p.ch7d || 0)) < 0.3
    && Math.abs((c.ch24h || 0) - (p.ch24h || 0)) < 0.3);
}

// Rizik 0–100 (veće = rizičnije). Namjerno jednostavno i objašnjivo.
function riskScore(c) {
  let r = 0;
  const flags = [];
  if (c.mcap < 200e6) { r += 22; flags.push('mali cap'); }
  else if (c.mcap < 1e9) r += 14;
  else if (c.mcap < 10e9) r += 6;

  if (c.vol < 5e6) { r += 12; flags.push('nizak promet'); }
  if (c.volToCap !== null) {
    if (c.volToCap < 0.005) { r += 10; flags.push('nelikvidan'); }
    else if (c.volToCap > 1) { r += 18; flags.push('promet>cap (pump/wash?)'); }
    else if (c.volToCap > 0.3) { r += 8; flags.push('pregrijan promet'); }
  }
  const a24 = Math.abs(c.ch24h || 0);
  const a7 = Math.abs(c.ch7d || 0);
  if (a24 > 15) { r += 14; flags.push('24h ekstremno'); } else if (a24 > 7) r += 7;
  if (a7 > 40) { r += 14; flags.push('7d ekstremno'); } else if (a7 > 20) r += 7;

  if (c.beta !== null) { if (c.beta > 1.6) r += 8; else if (c.beta > 1.3) r += 4; }
  if (c.fromAth !== null && c.fromAth < -90) { r += 8; flags.push('-90% od ATH'); }
  if (c.ageYears !== null) {
    if (c.ageYears < 1) { r += 10; flags.push('mlađi od 1g'); } else if (c.ageYears < 2) r += 5;
  }
  if (c.volChange24h !== null && c.volChange24h > 300) flags.push(`promet +${Math.round(c.volChange24h)}%`);

  r = Math.min(100, r);
  const level = r < 25 ? 'nizak' : r < 45 ? 'umjeren' : r < 65 ? 'visok' : 'vrlo visok';
  return { risk: r, riskLevel: level, flags };
}

// Momentum: težinski zbir kratkih i srednjih pomaka + odnos prema BTC-u
function momentumScore(c, btc) {
  const m = 0.55 * (c.ch7d || 0) + 0.3 * (c.ch24h || 0) + 0.15 * (c.ch6h || 0);
  const vsBtc7d = btc ? (c.ch7d || 0) - (btc.ch7d || 0) : null;
  return { momentum: round(m, 2), vsBtc7d: round(vsBtc7d, 2) };
}

// ───────────────────────────── 3. ANALIZA ─────────────────────────────
function analyze(raw) {
  const { fng, coins } = extract(raw);
  const all = coins.map(normalizeCoin).filter((c) => c.price !== null);
  const btc = all.find((c) => c.symbol === 'BTC');
  const eth = all.find((c) => c.symbol === 'ETH');

  const stables = [], wrapped = [], tooSmall = [], eligible = [];
  const seen = new Set(); // isti simbol više puta (bridged kopije) -> zadrži onaj sa najvećim capom
  for (const c of [...all].sort((x, y) => y.mcap - x.mcap)) {
    const dup = seen.has(c.symbol);
    seen.add(c.symbol);
    if (isStable(c)) stables.push(c);
    else if (dup || isWrapped(c, btc, eth)) wrapped.push(c);
    else if (c.mcap < CONFIG.minMarketCap || c.vol < CONFIG.minVolume24h) tooSmall.push(c);
    else eligible.push(Object.assign(c, riskScore(c), momentumScore(c, btc)));
  }
  const liquid = eligible.filter((c) => c.mcap >= CONFIG.liquidMarketCap && c.vol >= CONFIG.liquidVolume24h);

  // Sentiment
  let sentiment = null;
  if (fng && fng.length) {
    const vals = fng.map((d) => ({ v: num(d.value), cls: d.value_classification, t: num(d.timestamp) }))
      .filter((d) => d.v !== null).sort((a, b) => b.t - a.t);
    const avg = vals.reduce((s, d) => s + d.v, 0) / vals.length;
    const oldest = vals[vals.length - 1];
    sentiment = {
      now: vals[0].v, label: vals[0].cls, avg: round(avg, 1),
      change: vals[0].v - oldest.v, days: vals.length,
      min: Math.min(...vals.map((d) => d.v)), max: Math.max(...vals.map((d) => d.v)),
      series: vals.map((d) => d.v).reverse(),
    };
  }

  // Širina tržišta (breadth) – na kvalifikovanim coinima
  const totalCap = all.reduce((s, c) => s + c.mcap, 0);
  const capWeighted = (key) => {
    const w = eligible.reduce((s, c) => s + c.mcap, 0);
    return w ? eligible.reduce((s, c) => s + c.mcap * (c[key] || 0), 0) / w : null;
  };
  const breadth = {
    universe: all.length,
    eligible: eligible.length,
    excluded: { stables: stables.length, wrapped: wrapped.length, tooSmallOrIlliquid: tooSmall.length },
    up24hPct: round(100 * eligible.filter((c) => c.ch24h > 0).length / (eligible.length || 1), 1),
    up7dPct: round(100 * eligible.filter((c) => c.ch7d > 0).length / (eligible.length || 1), 1),
    beatBtc7dPct: round(100 * eligible.filter((c) => c.vsBtc7d > 0).length / (eligible.length || 1), 1),
    median24h: round(median(eligible.map((c) => c.ch24h)), 2),
    median7d: round(median(eligible.map((c) => c.ch7d)), 2),
    capWeighted24h: round(capWeighted('ch24h'), 2),
    capWeighted7d: round(capWeighted('ch7d'), 2),
    totalCap,
    btcDominance: btc ? round(100 * btc.mcap / totalCap, 1) : null,
    ethDominance: eth ? round(100 * eth.mcap / totalCap, 1) : null,
    stableShare: round(100 * stables.reduce((s, c) => s + c.mcap, 0) / totalCap, 1),
  };

  const by = (key, dir = -1) => (a, b) => dir * ((a[key] ?? -Infinity) - (b[key] ?? -Infinity));

  const lists = {
    topByCap: [...eligible].sort(by('mcap')).slice(0, CONFIG.topByCap),
    leaders7d: [...liquid].sort(by('ch7d')).slice(0, CONFIG.topMovers),
    laggards7d: [...liquid].sort(by('ch7d', 1)).slice(0, CONFIG.topMovers),
    volumeSpikes: liquid.filter((c) => c.volChange24h > 100).sort(by('volChange24h')).slice(0, CONFIG.topVolumeSpikes),
    // Kandidati: umjeren rizik, pozitivan trend, bolji od BTC-a, bez pregrijavanja
    candidates: liquid.filter((c) => c.risk < 45 && c.ch7d > 0 && c.ch24h > -3 && c.vsBtc7d > 0 && c.ch7d < 35)
      .sort(by('momentum')).slice(0, CONFIG.topCandidates),
    // Crvene zastavice: visok rizik + značajan promet (da nisu potpuno nebitni)
    redFlags: eligible.filter((c) => c.risk >= 55).sort((a, b) => b.risk - a.risk || b.mcap - a.mcap)
      .slice(0, CONFIG.topRedFlags),
    depegs: stables.filter((c) => c.mcap > 100e6 && Math.abs(c.price - 1) * 100 > CONFIG.stableDepegPct
      && !['SUSDS', 'SUSDE', 'EURC', 'EURS', 'SYRUPUSDC'].includes(c.symbol)),
  };

  return { generatedAt: new Date().toISOString(), dataTime: coins[0]?.last_updated || null,
    sentiment, btc, eth, breadth, lists };
}

// ───────────────────────────── 4. PORUKA ZA AGENTA ─────────────────────────────
function row(c) {
  return [c.symbol, price(c.price), usd(c.mcap), `v/c ${c.volToCap.toFixed(3)}`, `24h ${pct(c.ch24h)}`,
    `7d ${pct(c.ch7d)}`, `vsBTC ${pct(c.vsBtc7d)}`, `ATH ${pct(c.fromAth)}`, `β ${c.beta?.toFixed(2) ?? 'n/a'}`,
    `rizik ${c.risk} (${c.riskLevel})`].join(' | ') + (c.flags.length ? ` | ⚠ ${c.flags.join(', ')}` : '');
}

function buildMessage(a) {
  const L = [];
  const b = a.breadth;
  L.push(`# KRIPTO TRŽIŠTE – SNAPSHOT (${a.dataTime || a.generatedAt})`);
  L.push('');
  L.push('## Napomene o podacima');
  L.push(`- Analizirano ${b.universe} coina; kvalifikovano ${b.eligible} (isključeno: ${b.excluded.stables} stablecoina, `
    + `${b.excluded.wrapped} wrapped/staking derivata ili duplih simbola, ${b.excluded.tooSmallOrIlliquid} premalih/nelikvidnih: cap < ${usd(CONFIG.minMarketCap)} ili promet < ${usd(CONFIG.minVolume24h)}).`);
  L.push('- Izvor ne daje 30d i 1y promjene (sve su 0) – NE koristi ih. Dostupni horizonti: 1h, 6h, 24h, 7d i udaljenost od ATH.');
  L.push('- "v/c" = 24h promet / market cap. <0.005 nelikvidno, 0.02–0.15 zdravo, >0.3 pregrijano, >1 sumnjivo (pump/wash trading).');
  L.push('- "vsBTC" = 7d promjena minus 7d promjena BTC-a (relativna snaga). "β" = beta prema tržištu.');
  L.push('- "rizik" = 0–100 heuristika (veličina, likvidnost, volatilnost, beta, pad od ATH, starost projekta). Nije garancija.');
  L.push('');

  if (a.sentiment) {
    const s = a.sentiment;
    L.push('## Sentiment (Fear & Greed Index)');
    L.push(`- Sada: ${s.now} (${s.label}); prosjek ${s.days} dana: ${s.avg}; raspon ${s.min}–${s.max}; promjena u periodu: ${s.change > 0 ? '+' : ''}${s.change}.`);
    L.push(`- Serija (najstarije → najnovije): ${s.series.join(', ')}`);
    L.push(`- Tumačenje: ${s.now >= 75 ? 'ekstremna pohlepa – povećan rizik korekcije' : s.now >= 55 ? 'pohlepa – tržište optimistično, oprez sa jurenjem rasta'
      : s.now > 45 ? 'neutralno' : s.now > 25 ? 'strah – moguće prilike, ali trend slab' : 'ekstreman strah – istorijski zona akumulacije, visoka volatilnost'}.`);
    L.push('');
  }

  L.push('## Širina tržišta');
  if (a.btc) L.push(`- BTC: ${price(a.btc.price)} | 24h ${pct(a.btc.ch24h)} | 7d ${pct(a.btc.ch7d)} | od ATH ${pct(a.btc.fromAth)} (ATH ${a.btc.athDate})`);
  if (a.eth) L.push(`- ETH: ${price(a.eth.price)} | 24h ${pct(a.eth.ch24h)} | 7d ${pct(a.eth.ch7d)} | od ATH ${pct(a.eth.fromAth)} (ATH ${a.eth.athDate})`);
  L.push(`- Ukupni cap (praćeni coini): ${usd(b.totalCap)} | BTC dominacija ${b.btcDominance}% | ETH ${b.ethDominance}% | stablecoini ${b.stableShare}%`);
  L.push(`- U plusu 24h: ${b.up24hPct}% coina | u plusu 7d: ${b.up7dPct}% | bolji od BTC-a 7d: ${b.beatBtc7dPct}%`);
  L.push(`- Medijana: 24h ${pct(b.median24h)}, 7d ${pct(b.median7d)} | ponderisano capom: 24h ${pct(b.capWeighted24h)}, 7d ${pct(b.capWeighted7d)}`);
  L.push('');

  const section = (title, list, note) => {
    L.push(`## ${title}`);
    if (note) L.push(`_${note}_`);
    if (!list.length) L.push('- (nema)');
    list.forEach((c) => L.push(`- ${row(c)}`));
    L.push('');
  };
  section(`Top ${CONFIG.topByCap} po market capu (bez stablecoina i derivata)`, a.lists.topByCap);
  section('Kandidati – pozitivan trend uz umjeren rizik', a.lists.candidates,
    'rizik < 45, 7d > 0 i bolji od BTC-a, 24h > -3%, 7d < +35% (nije pregrijan), cap ≥ $100M, promet ≥ $5M');
  section('Najjači 7d (likvidni)', a.lists.leaders7d);
  section('Najslabiji 7d (likvidni)', a.lists.laggards7d);
  section('Skok prometa 24h (moguća vijest/događaj)', a.lists.volumeSpikes, 'promet porastao >100% za 24h');
  section('Crvene zastavice – visok rizik', a.lists.redFlags);
  if (a.lists.depegs.length) {
    L.push('## ⚠ Stablecoini van pariteta');
    a.lists.depegs.forEach((c) => L.push(`- ${c.symbol}: ${price(c.price)} (cap ${usd(c.mcap)})`));
    L.push('');
  }

  L.push('## Zadatak');
  L.push('Na osnovu ovih podataka: (1) procijeni opšte stanje tržišta i sentiment, (2) predloži raspodjelu kapitala po '
    + 'kategorijama rizika (npr. % u BTC/ETH, % u kandidate, % u stablecoinima), (3) navedi konkretne coine koje vrijedi '
    + 'pratiti i zašto, (4) navedi šta izbjegavati i zašto, (5) navedi glavne rizike i šta bi promijenilo procjenu. '
    + 'Oslanjaj se samo na brojke iznad; ako nešto ne možeš zaključiti iz podataka, reci to.');
  return L.join('\n');
}

// ───────────────────────────── 5. POKRETANJE ─────────────────────────────
function run(raw) {
  const analysis = analyze(raw);
  const message = buildMessage(analysis);
  // summary = strukturirani podaci, ako agentu želiš dati i JSON (skraćeno)
  const slim = (c) => ({ symbol: c.symbol, price: c.price, mcap: c.mcap, ch24h: c.ch24h, ch7d: c.ch7d,
    vsBtc7d: c.vsBtc7d, volToCap: round(c.volToCap, 4), fromAth: c.fromAth, risk: c.risk, flags: c.flags });
  const summary = { ...analysis, btc: undefined, eth: undefined,
    lists: Object.fromEntries(Object.entries(analysis.lists).map(([k, v]) => [k, v.map(slim)])) };
  return { message, summary };
}

// n8n Code node
if (typeof $input !== 'undefined') {
  return [{ json: run($input.all().map((i) => i.json)) }];
}

// Node.js CLI
if (typeof require !== 'undefined' && typeof module !== 'undefined' && require.main === module) {
  const fs = require('fs');
  const file = process.argv[2];
  if (!file) { console.error('Upotreba: node crypto-agent-prompt.js podaci.json [--json]'); process.exit(1); }
  const result = run(JSON.parse(fs.readFileSync(file, 'utf8')));
  console.log(process.argv.includes('--json') ? JSON.stringify(result, null, 2) : result.message);
}

if (typeof module !== 'undefined') module.exports = { run, analyze, buildMessage, CONFIG };

const LIMIT = 4000;
const out = [];
for (const item of $input.all()) {
  const text = String(item.json.output || '');
  const lines = text.split('\n');
  let chunk = '';
  for (let line of lines) {
    while (line.length > LIMIT) {
      if (chunk) { out.push(chunk); chunk = ''; }
      out.push(line.slice(0, LIMIT));
      line = line.slice(LIMIT);
    }
    const next = chunk ? chunk + '\n' + line : line;
    if (next.length > LIMIT) { out.push(chunk); chunk = line; } else { chunk = next; }
  }
  if (chunk.trim()) out.push(chunk);
}
return out.map(text => ({ json: { text } }));
